-- ComfyClub - authoritative product reviews (customer-provided counts).
-- 442 reviews across 60 products. Preserves each product's exact review count,
-- ratings, reviewer names and cities; review text drawn from an expanded natural
-- pool so wording varies. All approved. Idempotent on re-run.
BEGIN;

-- Featured flag (used by the dashboard Reviews manager + storefront ordering).
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS is_featured BOOLEAN DEFAULT false;

DELETE FROM reviews
WHERE status='approved' AND admin_reply IS NULL AND image_url IS NULL;



SELECT refresh_product_ratings();
COMMIT;
